{
 "project": "E-GOVERNANCE MISSION MODE PROJECT (MMP) CRIME & CRIMINAL TRACKING NETWORK AND SYSTEMS (CCTNS) FUNCTIONAL REQUIREMENTS SPECIFICATION V1.0 (DRAFT) MINISTRY OF HOME AFFAIRS GOVERNMENT OF INDIA",
 "meeting": "1 of 1 (kickoff)",
 "participants": [
  "Analyst",
  "Client",
  "EndUser",
  "TechLead"
 ],
 "previous_turns_for_context_only": [
  {
   "speaker": "TechLead",
   "act": "confirm"
  },
  {
   "speaker": "Client",
   "act": "state",
   "content": [
    "Placing navigation components consistently: Navigation components should be placed consistently on the pages or in the framesets in the pages of the application.",
    "Taking account of the users' tasks and information needs: When providing different access paths or navigation structures for different user groups, the tasks and information needs of these user groups should be taken into consideration."
   ]
  },
  {
   "speaker": "TechLead",
   "act": "state",
   "content": [
    "Making individualization and adaptation evident: It should be made evident to the user when individualization and/or adaptation are used.",
    "Making user profiles evident: If predefined user profiles or user-specified profiles are used for individualizing or adapting content, the profile currently used should be made evident. If profiles are used, it is important to provide users with information about this concept and its implications."
   ]
  }
 ],
 "turns": [
  {
   "id": "M1:T61",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Allowing users to see and change profiles: If user-specified profiles are used, users should be able to see, modify and delete that profile on demand.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T62",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'system availability' and asks about it."
  },
  {
   "id": "M1:T63",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The planned downtime for the System must not exceed <xx> hours per <rolling three month period>. The System is considered to be down if any user is unable to perform any normal System function and if this failure is attributed to any component of the System other than the workstation.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T64",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T65",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Unplanned downtime for the System must not exceed <xx hours/minutes> per <rolling three month period>.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T66",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T67",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The number of incidents of unplanned downtime for the System must not exceed <x> per <rolling three month period>.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T68",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "In the event of any software or hardware failure, it must be possible to restore the System (with inline synchronization) within no more than <xx> hours.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T69",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'performance and scalability' and asks about it."
  },
  {
   "id": "M1:T70",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The System must provide adequate response times for commonly performed functions under both standard and peak conditions",
     "role": "statement"
    },
    {
     "text": "The System must be able to perform a simple search within 5-8 seconds and a advanced search (multiple search criteria) within 10-15 seconds regardless of the storage capacity or number of cases in the system. In this context, performing a search means returning a result list. It does not include retrieving the records themselves.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T71",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T72",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The System must be able to retrieve and display within 5-8 seconds the case which has been accessed within the previous 2 months, regardless of storage capacity or number of cases in the system. This requirement is intended to allow for rapid retrieval of frequently-used cases, on the understanding that frequency of use is typically correlated with recent use.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T73",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The System be scaleable and must not have any features which would preclude use in small or large police stations, with varying numbers of cases handled.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T74",
   "speaker": "Analyst",
   "act": "anything_else",
   "guide": "Analyst asks whether there is anything else on 'performance and scalability'."
  },
  {
   "id": "M1:T75",
   "speaker": "TechLead",
   "act": "nothing_else",
   "guide": "Short answer: nothing else on this topic."
  },
  {
   "id": "M1:T76",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'system functionality' and asks about it."
  },
  {
   "id": "M1:T77",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The system should support multilingual interface",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T78",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The system should be designed in manner that operational data is not lost in case of any failure of equipment or communication network.",
     "role": "statement"
    },
    {
     "text": "The system should work even in an offline mode with the critical functionality",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T79",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The system should be implemented using Service Oriented Architecture (SOA) and have a modular design",
     "role": "statement"
    },
    {
     "text": "The system should be developed for a centralized deployment and maintenance",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T80",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  }
 ]
